/**
 * @byway/recipe's table of what each template shows (ADR-0097) is this library's, written down: generated by
 * `pnpm prompts:slots` and held equal to the templates here, so admission never reads a template other than the one the
 * runner renders. The table records the slots a template declares, which the library holds equal to the slots its text
 * uses; that is what it shows only while every slot a template uses is one whose value it inserts, which this test holds
 * too (a slot used only as an `{{#if}}` condition would show nothing of its value).
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import type { BodyNode } from '../src/syntax.ts';
import { TEMPLATE_SLOTS_FILE, templateSlotsText } from '../src/emit-template-slots.ts';
import { FILES, library } from './library.ts';

/** The slots whose value a body inserts somewhere, on any branch. */
function inserted(nodes: readonly BodyNode[], into = new Set<string>()): Set<string> {
  for (const n of nodes) {
    if (n.kind === 'slot') into.add(n.name);
    if (n.kind === 'if') {
      inserted(n.then, into);
      inserted(n.otherwise, into);
    }
  }
  return into;
}

describe('the template-slots table in @byway/recipe', () => {
  it('is the one this library generates (run `pnpm prompts:slots` after editing a template)', () => {
    expect(readFileSync(TEMPLATE_SLOTS_FILE, 'utf8').replace(/\r\n/g, '\n')).toBe(templateSlotsText(library));
  });

  it('records what a template shows: every slot a template uses, it inserts', () => {
    for (const { name, template } of FILES) {
      const shown = inserted(template.user, template.system ? inserted(template.system) : new Set());
      expect(template.slots.filter((s) => !shown.has(s)), name).toEqual([]);
    }
  });
});
